fileContents.midnightntwrk/midnight-js@v5.0.0-beta.6::
{
  "name": "@midnight-ntwrk/midnight-js",
  "version": "5.0.0-beta.6",
  "description": "Barrel package for Midnight.js core framework",
  "main": "dist/index.cjs",
  "module": "dist/index.mjs",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": {
        "import": "./dist/index.d.mts",
        "require": "./dist/index.d.cts"
      },
      "import": "./dist/index.mjs",
      "require": "./dist/index.cjs"
    },
    "./contracts": {
      "types": {
        "import": "./dist/contracts.d.mts",
        "require": "./dist/contracts.d.cts"
      },
      "import": "./dist/contracts.mjs",
      "require": "./dist/contracts.cjs"
    },
    "./network-id": {
      "types": {
        "import": "./dist/network-id.d.mts",
        "require": "./dist/network-id.d.cts"
      },
      "import": "./dist/network-id.mjs",
      "require": "./dist/network-id.cjs"
    },
    "./types": {
      "types": {
        "import": "./dist/types.d.mts",
        "require": "./dist/types.d.cts"
      },
      "import": "./dist/types.mjs",
      "require": "./dist/types.cjs"
    },
    "./utils": {
      "types": {
        "import": "./dist/utils.d.mts",
        "require": "./dist/utils.d.cts"
      },
      "import": "./dist/utils.mjs",
      "require": "./dist/utils.cjs"
    },
    "./package.json": "./package.json"
  },
  "sideEffects": false,
  "repository": "git@github.com:midnight-ntwrk/artifacts",
  "packageManager": "yarn@4.14.1",
  "author": "IOHK",
  "license": "Apache-2.0",
  "scripts": {
    "clean": "rm -rf dist tsconfig.build.tsbuildinfo .rollup.cache reports coverage",
    "build": "rollup -c rollup.config.mjs",
    "test": "vitest run --passWithNoTests",
    "deploy": "yarn npm publish --tolerate-republish"
  },
  "dependencies": {
    "@midnight-ntwrk/midnight-js-contracts": "workspace:*",
    "@midnight-ntwrk/midnight-js-network-id": "workspace:*",
    "@midnight-ntwrk/midnight-js-protocol": "workspace:*",
    "@midnight-ntwrk/midnight-js-types": "workspace:*",
    "@midnight-ntwrk/midnight-js-utils": "workspace:*"
  },
  "devDependencies": {
    "@rollup/plugin-typescript": "^12.3.0",
    "rollup": "^4.60.4",
    "rollup-plugin-dts": "^6.4.1",
    "typescript": "^6.0.3",
    "vitest": "^4.1.7"
  },
  "files": [
    "dist/"
  ],
  "engines": {
    "node": ">=22"
  }
}

